def minSum(A, N):
    mp = {}
    sum = 0
    for i in range(N):
        sum += A[i]
        if A[i] in mp:
            mp[A[i]] += 1
        else:
            mp[A[i]] = 1
    minSum = float('inf')
    for it in mp:
        minSum = min(minSum, sum - (it * mp[it]))
    return minSum
