import java.util.*;

class Node {
    String value;
    List<Node> children;

    public Node(String value) {
        this.value = value;
        this.children = new ArrayList<>();
    }

    public void addChild(Node child) {
        this.children.add(child);
    }
}

public class ProductCalculator {
    public static int productAtKthLevel(Node tree, int k) {
        int level = -1;
        int product = 1;
        int n = tree.children.size();
        for (int i = 0; i < n; i++) {
            if (tree.children.get(i).value.equals(" (")) {
                level++;
            } else if (tree.children.get(i).value.equals(") ")) {
                level--;
            } else {
                if (level == k) {
                    product *= (Integer.parseInt(tree.children.get(i).value) - Integer.parseInt("0"));
                }
            }
        }
        return product;
    }

    public static void main(String[] args) {
        Node tree = new Node(" (0(5(6 () ()) (4 () (9 () ()))) (7(1 () ()) (3 () ()))) ");
        int k = 2;
        int result = productAtKthLevel(tree, k);
        System.out.println(result); // Output: 18
    }
}

