    for i in range(1 << n):
        bitwiseAND = - 1;
        bitwiseOR = 0;
        bitwiseXOR = 0;
        for j in range(n):
            if(i & (1 << j)):
                if(bitwiseAND == - 1):
                    bitwiseAND = a[j];
                else:
                    bitwiseAND &= a[j];
                bitwiseOR |= a[j];
                bitwiseXOR ^= a[j];
