import java.util.regex.*;

class Quadrant {
    public static String quadrant(String s) {
        Pattern pattern = Pattern.compile("(\\d+) + (\\d+)");
        Matcher matcher = pattern.matcher(s);
        if (matcher.find()) {
            String real = matcher.group(1);
            String imaginary = matcher.group(2);
            int x = Integer.parseInt(real);
            int y = Integer.parseInt(imaginary);
            if (x > 0 && y > 0) {
                return "Quadrant 1";
            } else if (x < 0 && y > 0) {
                return "Quadrant 2";
            } else if (x < 0 && y < 0) {
                return "Quadrant 3";
            } else if (x > 0 && y < 0) {
                return "Quadrant 4";
            } else if (x == 0 && y > 0) {
                return "Lies on the positive X-axis";
            } else if (x == 0 && y < 0) {
                return "Lies on the negative X-axis";
            } else if (y == 0 && x < 0) {
                return "Lies on the negative Y-axis";
            } else {
                return "Lies on the origin";
            }
        }
        return "Invalid input format";
    }

