        sum = (mid * (mid + 1)) >> 1;
        if(sum <= n):
            count = int(mid / k);
            low = mid + 1;
        else:
            high = mid - 1;
    last = (count * k);
    n -= int((last * (last + 1)) / 2);
    i = 0;
    term = (count * k) + 1;
    while(n):
        if(term <= n):
            arr[i] = term;
            i += 1;
            n -= term;
            term += 1;
        else:
            arr[i] += n;
            n = 0;
