public class ArrayXor {
    public static int xorOperations(int N, int[] arr, int M, int K) {
        if (M < 0 || M >= N) {
            return -1;
        }
        if (K < 0 || K >= N - M) {
            return -1;
        }
        for (int i = 0; i < M; i++) {
            int temp = arr[i];
            arr[i] ^= arr[i + 1];
            arr[i + 1] = temp;
        }
        return arr[K];
    }

