import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Tokenizer {
    public static List<String> tokenizeUnquoted(String text) {
        List<String> tokens = new ArrayList<>();
        int first = 0;
        while (first < text.length()) {
            first = skipWhitespace(text, first);
            int last = scanToken(text, first);
            if (first < last) {
                tokens.add(text.substring(first, last));
            }
        }
        return tokens;
    }

    private static int skipWhitespace(String text, int start) {
        while (start < text.length() && Character.isWhitespace(text.charAt(start))) {
            start++;
        }
        return start;
    }

    private static int scanToken(String text, int start) {
        int end = start + 1;
        while (end < text.length() && Character.isLetterOrDigit(text.charAt(end))) {
            end++;
        }
        return end;
    }

    public static void main(String[] args) {
        System.out.println(tokenizeUnquoted("This is a test."));
    }
}
